def fix_thumbnails(apps, schema_editor):
    """maxresdefault.jpg n'existe pas pour toutes les vidéos YouTube : on passe en hqdefault.jpg."""
    Video = apps.get_model('videos', 'Video')
    for video in Video.objects.filter(thumbnail_url__contains='maxresdefault'):
        video.thumbnail_url = video.thumbnail_url.replace('maxresdefault', 'hqdefault')
        video.save(update_fields=['thumbnail_url'])


